32	
33	namespace {
34	/**
35	 * @brief for acl graph calculates the max workspace size based on the specific calculation process.
36	 * declaration here for testcase to use by extern the interface
37	 * @domain aclnn_ops_infer
38	 */
39	
40	extern "C" aclnnStatus __attribute__((weak)) NnopbaseDisableOptionalInput(void *executor, const size_t irIndex);
41	
42	aclnnStatus aclnnAiInfraSparseFlashAttentionGqaGetMaxWorkspaceSize(const aclTensor *query,
43	                                                                   const aclTensorList *key,
44	                                                                   const aclTensorList *value,
45	                                                                   const aclTensor *sparseIndices,
46	                                                                   double scaleValue,
47	                                                                   int64_t sparseBlockSize,
48	                                                                   const aclIntArray *actualSeqLengthsOptional,
49	                                                                   const aclIntArray *actualSeqLengthsKvOptional,
50	                                                                   const aclTensor *blockTableOptional,
51	                                                                   int64_t numHeads,
52	                                                                   int64_t numKeyValueHeads,
53	                                                                   char *inputLayout,
54	                                                                   char *inputLayoutKv,
55	                                                                   int64_t sparseMode,
56	                                                                   int64_t blockSize,
57	                                                                   bool softmaxLseFlag,
58	                                                                   const aclTensor *attentionOut,
59	                                                                   const aclTensor *softmaxLse,
60	                                                                   uint64_t *workspaceSize,
61	                                                                   aclOpExecutor **executor)
62	{
63	    const aclTensor *placeHolder = nullptr;
64	    const aclTensor *tempTensor = nullptr;
65	    const aclTensor *deqScale1Optional = nullptr;
66	    const aclTensor *pseShiftOptional = nullptr;
67	    const aclTensor *attenMaskOptional = nullptr;
68	    const aclTensor *quantScale1Optional = nullptr;
69	    const aclTensor *deqScale2Optional = nullptr;
70	    const aclTensor *quantScale2Optional = nullptr;
71	    const aclTensor *quantOffset2Optional = nullptr;
72	    const aclTensor *antiquantScaleOptional = nullptr;
73	    const aclTensor *antiquantOffsetOptional = nullptr;
74	    const aclTensor *queryPaddingSizeOptional = nullptr;
75	    const aclTensor *kvPaddingSizeOptional = nullptr;
76	    const aclTensor *keyAntiquantScaleOptional = nullptr;
77	    const aclTensor *keyAntiquantOffsetOptional = nullptr;
78	    const aclTensor *valueAntiquantScaleOptional = nullptr;
79	    const aclTensor *valueAntiquantOffsetOptional = nullptr;
80	    const aclTensor *keySharedPrefixOptional = nullptr;
81	    const aclTensor *valueSharedPrefixOptional = nullptr;
82	    const aclIntArray *actualSharedPrefixLenOptional = nullptr;
83	    const aclTensor *queryRopeOptional = nullptr;
84	    const aclTensor *keyRopeOptional = nullptr;
85	    const aclTensor *keyRopeAntiquantScaleOptional = nullptr;
86	    const aclTensor *dequantScaleQueryOptional = nullptr;
87	    const aclTensor *learnableSinkOptional = nullptr;
88	    const aclTensor *tensorKeySharedPrefixOptional = nullptr;
89	    const aclTensor *tensorValueSharedPrefixOptional = nullptr;
90	    int64_t preTokens = 65535;
91	    int64_t nextTokens = 65535;
92	    int64_t innerPrecise = 0;
93	    int64_t antiquantMode = 0;
94	    int64_t keyAntiquantMode = 0;
95	    int64_t valueAntiquantMode = 0;
96	    int64_t queryQuantMode = 0;
97	
98	    OP_LOGD("start aclnnAiInfraSparseFlashAttentionGqaGetMaxWorkspaceSize");
99	    TensorPreProcessSfa(key, value);
100	    PrefixTensorPreProcessSfa(tensorKeySharedPrefixOptional, tensorValueSharedPrefixOptional);
101	
102	    aclTensor *fakeActualSeqLengthsOptional{nullptr};
103	    aclTensor *fakeActualSeqLengthsKvOptional{nullptr};
104	    aclTensor *fakeActualSharedPrefixLenOptional{nullptr};
105	
106	    // nullptr不处理， nullptr是空指针，这样不会影响原来就不传入actual seq length为空的逻辑
107	    aclnnStatus ret = FakeArraySfa(actualSeqLengthsOptional, fakeActualSeqLengthsOptional);
108	    CHECK_RET_CODE(ret, "Try alloc fake actualSeqLengthsOptional failed");
109	    ret = FakeArraySfa(actualSeqLengthsKvOptional, fakeActualSeqLengthsKvOptional);
110	    if (ret != ACLNN_SUCCESS) {
111	        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try alloc fake actualSeqLengthsKvOptional failed");
112	        aclDestroyTensor(fakeActualSeqLengthsOptional); // 没有返回值无需校验
113	        return ret;
114	    }
115	
116	    ret = FakeArraySfa(actualSharedPrefixLenOptional, fakeActualSharedPrefixLenOptional);
117	    if (ret != ACLNN_SUCCESS) {
118	        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try alloc fake actualSharedPrefixLenOptional failed");
119	        aclDestroyTensor(fakeActualSeqLengthsOptional); // 没有返回值无需校验
120	        aclDestroyTensor(fakeActualSeqLengthsKvOptional);
121	        return ret;
122	    }
123	
124	    AiInfraSparseFlashAttentionGqaProcessSoftmaxLse(softmaxLseFlag, softmaxLse, tempTensor, placeHolder);
125	
126	    ret = aclnnInnerAiInfraSparseFlashAttentionGqaTensorGetWorkspaceSize(query,
127	                                                                         key,
128	                                                                         value,
129	                                                                         sparseIndices,
130	                                                                         pseShiftOptional,
131	                                                                         attenMaskOptional,
132	                                                                         fakeActualSeqLengthsOptional,
133	                                                                         fakeActualSeqLengthsKvOptional,
134	                                                                         deqScale1Optional,
135	                                                                         quantScale1Optional,
136	                                                                         deqScale2Optional,
137	                                                                         quantScale2Optional,
138	                                                                         quantOffset2Optional,
139	                                                                         antiquantScaleOptional,
140	                                                                         antiquantOffsetOptional,
141	                                                                         blockTableOptional,
142	                                                                         queryPaddingSizeOptional,
143	                                                                         kvPaddingSizeOptional,
144	                                                                         keyAntiquantScaleOptional,
145	                                                                         keyAntiquantOffsetOptional,
146	                                                                         valueAntiquantScaleOptional,
147	                                                                         valueAntiquantOffsetOptional,
148	                                                                         tensorKeySharedPrefixOptional,
149	                                                                         tensorValueSharedPrefixOptional,
150	                                                                         fakeActualSharedPrefixLenOptional,
151	                                                                         queryRopeOptional,
152	                                                                         keyRopeOptional,
153	                                                                         keyRopeAntiquantScaleOptional,
154	                                                                         dequantScaleQueryOptional,
155	                                                                         learnableSinkOptional,
156	                                                                         nullptr,
157	                                                                         nullptr,
158	                                                                         numHeads,
159	                                                                         sparseBlockSize,
160	                                                                         scaleValue,
161	                                                                         preTokens,
162	                                                                         nextTokens,
163	                                                                         inputLayout,
164	                                                                         inputLayoutKv,
165	                                                                         numKeyValueHeads,
166	                                                                         sparseMode,
167	                                                                         innerPrecise,
168	                                                                         blockSize,
169	                                                                         antiquantMode,
170	                                                                         softmaxLseFlag,
171	                                                                         keyAntiquantMode,
172	                                                                         valueAntiquantMode,
173	                                                                         queryQuantMode,
174	                                                                         0,
175	                                                                         0,
176	                                                                         attentionOut,
177	                                                                         placeHolder,
178	                                                                         workspaceSize,
179	                                                                         executor);
180	    if (softmaxLseFlag == false) {
181	        aclDestroyTensor(tempTensor);
182	    }
183	    aclDestroyTensor(fakeActualSeqLengthsOptional); // 只会成功，无需校验
184	    aclDestroyTensor(fakeActualSeqLengthsKvOptional);
185	    aclDestroyTensor(fakeActualSharedPrefixLenOptional);
186	    return ret;
187	}
188	
189	aclnnStatus aclnnAiInfraSparseFlashAttentionGqaGetWorkspaceSize(const aclTensor *query,
190	                                                                const aclTensorList *key,
191	                                                                const aclTensorList *value,
192	                                                                const aclTensor *sparseIndices,
193	                                                                double scaleValue,
194	                                                                int64_t sparseBlockSize,
195	                                                                const aclIntArray *actualSeqLengthsOptional,
196	                                                                const aclIntArray *actualSeqLengthsKvOptional,
197	                                                                const aclTensor *blockTableOptional,
198	                                                                int64_t numHeads,
199	                                                                int64_t numKeyValueHeads,
200	                                                                char *inputLayout,
201	                                                                char *inputLayoutKv,
202	                                                                int64_t sparseMode,
203	                                                                int64_t blockSize,
204	                                                                bool softmaxLseFlag,
205	                                                                const aclTensor *attentionOut,
206	                                                                const aclTensor *softmaxLse,
207	                                                                uint64_t *workspaceSize,
208	                                                                aclOpExecutor **executor)
209	{
210	    const aclTensorList *tensorListKey = key;
211	    const aclTensorList *tensorListValue = value;
212	    TensorPreProcessSfa(tensorListKey, tensorListValue);
213	
214	    const aclTensor *placeHolder = nullptr;
215	    const aclTensor *tempTensor = nullptr;
216	    const aclTensor *deqScale1Optional = nullptr;
217	    const aclTensor *pseShiftOptional = nullptr;
218	    const aclTensor *attenMaskOptional = nullptr;
219	    const aclTensor *quantScale1Optional = nullptr;
220	    const aclTensor *deqScale2Optional = nullptr;
221	    const aclTensor *quantScale2Optional = nullptr;
222	    const aclTensor *quantOffset2Optional = nullptr;
223	    const aclTensor *antiquantScaleOptional = nullptr;
224	    const aclTensor *antiquantOffsetOptional = nullptr;
225	    const aclTensor *queryPaddingSizeOptional = nullptr;
226	    const aclTensor *kvPaddingSizeOptional = nullptr;
227	    const aclTensor *keyAntiquantScaleOptional = nullptr;
228	    const aclTensor *keyAntiquantOffsetOptional = nullptr;
229	    const aclTensor *valueAntiquantScaleOptional = nullptr;
230	    const aclTensor *valueAntiquantOffsetOptional = nullptr;
231	    const aclTensor *keySharedPrefixOptional = nullptr;
232	    const aclTensor *valueSharedPrefixOptional = nullptr;
233	    const aclIntArray *actualSharedPrefixLenOptional = nullptr;
234	    const aclTensor *queryRopeOptional = nullptr;
235	    const aclTensor *keyRopeOptional = nullptr;
236	    const aclTensor *keyRopeAntiquantScaleOptional = nullptr;
237	    const aclTensor *dequantScaleQueryOptional = nullptr;
238	    const aclTensor *learnableSinkOptional = nullptr;
239	    const aclTensor *tensorKeySharedPrefixOptional = nullptr;
240	    const aclTensor *tensorValueSharedPrefixOptional = nullptr;
241	    int64_t preTokens = 65535;
242	    int64_t nextTokens = 65535;
243	    int64_t innerPrecise = 0;
244	    int64_t antiquantMode = 0;
245	    int64_t keyAntiquantMode = 0;
246	    int64_t valueAntiquantMode = 0;
247	    int64_t queryQuantMode = 0;
248	
249	    AiInfraSparseFlashAttentionGqaProcessSoftmaxLse(softmaxLseFlag, softmaxLse, tempTensor, placeHolder);
250	
251	    aclnnStatus ret = aclnnInnerAiInfraSparseFlashAttentionGqaGetWorkspaceSize(query,
252	                                                                               tensorListKey,
253	                                                                               tensorListValue,
254	                                                                               sparseIndices,
255	                                                                               pseShiftOptional,
256	                                                                               attenMaskOptional,
257	                                                                               actualSeqLengthsOptional,
258	                                                                               actualSeqLengthsKvOptional,
259	                                                                               deqScale1Optional,
260	                                                                               quantScale1Optional,
261	                                                                               deqScale2Optional,
262	                                                                               quantScale2Optional,
263	                                                                               quantOffset2Optional,
264	                                                                               antiquantScaleOptional,
265	                                                                               antiquantOffsetOptional,
266	                                                                               blockTableOptional,
267	                                                                               queryPaddingSizeOptional,
268	                                                                               kvPaddingSizeOptional,
269	                                                                               keyAntiquantScaleOptional,
270	                                                                               keyAntiquantOffsetOptional,
271	                                                                               valueAntiquantScaleOptional,
272	                                                                               valueAntiquantOffsetOptional,
273	                                                                               tensorKeySharedPrefixOptional,
274	                                                                               tensorValueSharedPrefixOptional,
275	                                                                               actualSharedPrefixLenOptional,
276	                                                                               queryRopeOptional,
277	                                                                               keyRopeOptional,
278	                                                                               keyRopeAntiquantScaleOptional,
279	                                                                               dequantScaleQueryOptional,
280	                                                                               learnableSinkOptional,
281	                                                                               nullptr,
282	                                                                               nullptr,
283	                                                                               numHeads,
284	                                                                               sparseBlockSize,
285	                                                                               scaleValue,
286	                                                                               preTokens,
287	                                                                               nextTokens,
288	                                                                               inputLayout,
289	                                                                               inputLayoutKv,
290	                                                                               numKeyValueHeads,
291	                                                                               sparseMode,
292	                                                                               innerPrecise,
293	                                                                               blockSize,
294	                                                                               antiquantMode,
295	                                                                               softmaxLseFlag,
296	                                                                               keyAntiquantMode,
297	                                                                               valueAntiquantMode,
298	                                                                               queryQuantMode,
299	                                                                               0,
300	                                                                               0,
301	                                                                               attentionOut,
302	                                                                               placeHolder,
303	                                                                               workspaceSize,
304	                                                                               executor);
305	    if (softmaxLseFlag == false) {
306	        aclDestroyTensor(tempTensor);
307	    }
308	    if (ret == 0) {
309	        if (NnopbaseDisableOptionalInput != nullptr) {
310	            NnopbaseDisableOptionalInput(*executor, 29U); // 29 is input irIndex，占位符
311	            NnopbaseDisableOptionalInput(*executor, 30U); // 30 is input irIndex，占位符
312	        }
313	    }
314	    return ret;
315	}
316	
317	aclnnStatus aclnnAiInfraSparseFlashAttentionGqa(void *workspace,
318	                                                uint64_t workspaceSize,
319	                                                aclOpExecutor *executor,
320	                                                const aclrtStream stream)
321	{
322	    return aclnnInnerAiInfraSparseFlashAttentionGqa(workspace, workspaceSize, executor, stream);
323	}
324	
325	} // namespace
326	
327	#ifdef __cplusplus
328	}
329	#endif

