 */

#include "ai_infra_sfa_tiling_nonquant.h"
#include <map>
#include <vector>
#include <numeric>
#include <algorithm>
#include <graph/utils/type_utils.h>
#include "fia_tiling_templates_registry.h"
#include "ai_infra_sparse_flash_attention_gqa_split_core.h"
#include "../op_kernel/ai_infra_sparse_flash_attention_gqa_template_tiling_key.h"

using namespace ge;
using namespace AscendC;
namespace optiling {

namespace optilingSfa {

constexpr uint64_t PRE_LOAD_NUM_MLA = 2;
constexpr uint32_t BLOCK_TABLE_ELEM_BYTE = 4;

constexpr uint64_t SFA_TILINGKEYOFFSET = uint64_t(100000000000000000UL);
constexpr uint64_t SFA_PERF_MODE_TILINGKEYOFFSET = uint64_t(1000000000000000UL);

constexpr uint32_t G_SIZE_128 = 128;
constexpr uint32_t S1_SIZE_16 = 16;

constexpr uint32_t QK_HEAD_DIM_64 = 64;
constexpr uint32_t QK_HEAD_DIM_128 = 128;
constexpr uint32_t QK_HEAD_DIM_192 = 192;

constexpr uint32_t ROPE_HEAD_DIM_0 = 0;
constexpr uint32_t ROPE_HEAD_DIM_64 = 64;

constexpr uint32_t V_HEAD_DIM_64 = 64;
constexpr uint32_t V_HEAD_DIM_128 = 128;

constexpr uint32_t S_INNER_SIZE_512 = 512;
constexpr uint32_t S_INNER_SIZE_1024 = 1024;

constexpr uint32_t S_INNER_SIZE_ALIGN_512 = 512;
constexpr uint32_t S_INNER_SIZE_ALIGN_1024 = 1024;
constexpr uint32_t S_INNER_SIZE_ALIGN_2048 = 2048;
constexpr uint32_t S_INNER_SIZE_ALIGN_4096 = 4096;

constexpr int32_t SPARSE_MODE_2 = 2;
constexpr int32_t SPARSE_MODE_3 = 3;
constexpr int32_t SPARSE_MODE_4 = 4;

constexpr uint32_t M_BASE_SIZE_32 = 32;
constexpr uint32_t M_BASE_SIZE_64 = 64;
constexpr uint32_t M_BASE_SIZE_128 = 128;
constexpr uint32_t M_BASE_SIZE_256 = 256;
constexpr uint32_t M_BASE_SIZE_512 = 512;

template <typename T> inline auto Align(T num, T rnd) -> T
{
    return (((rnd) == 0) ? 0 : (((num) + (rnd)-1) / (rnd) * (rnd)));
}

constexpr uint64_t RecursiveSum()
{
    return 0;
}

template <typename T, typename... Args> constexpr uint64_t RecursiveSum(T templateId, Args... templateIds)
{
    return static_cast<uint64_t>(templateId) + 10U * RecursiveSum(templateIds...);
}

template <typename... Args> constexpr uint64_t SFA_GET_TILINGKEY(Args... templateIds)
{
    return RecursiveSum(templateIds...);
}

void SfaTilingNonQuant::InitTilingInfo(TilingInfo *tilingInfo)
{
    sfaInfo_ = static_cast<FiaTilingInfo *>(tilingInfo);
}

ge::graphStatus SfaTilingNonQuant::GetPlatformInfo()
{
    OPS_CHECK(sfaInfo_->platformInfo == nullptr,
              OPS_REPORT_VECTOR_INNER_ERR(sfaInfo_->opName, "GetPlatformInfo is nullptr."),
              return ge::GRAPH_FAILED);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(sfaInfo_->platformInfo);
    libapiSize_ = ascendcPlatform.GetLibApiWorkSpaceSize();
    aivNum_ = ascendcPlatform.GetCoreNumAiv();
    aicNum_ = ascendcPlatform.GetCoreNumAic();

    OPS_CHECK(aicNum_ == 0 || aivNum_ == 0,
              OPS_REPORT_VECTOR_INNER_ERR(sfaInfo_->opName, "num of core obtained is 0."),
              return GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

bool SfaTilingNonQuant::IsCapable()
{
    if (sfaInfo_ == nullptr) {
        return false;
    }

    ge::DataType qDataType = sfaInfo_->inputQType;
    ge::DataType kDataType = sfaInfo_->inputKvType;

    if ((qDataType == ge::DT_FLOAT16 || qDataType == ge::DT_BF16) && (qDataType == kDataType)) {
        if ((sfaInfo_->qkHeadDim == QK_HEAD_DIM_128 && sfaInfo_->ropeHeadDim == ROPE_HEAD_DIM_0 &&
             sfaInfo_->vHeadDim == V_HEAD_DIM_128) ||
            (sfaInfo_->qkHeadDim == QK_HEAD_DIM_64 && sfaInfo_->ropeHeadDim == ROPE_HEAD_DIM_0 &&
             sfaInfo_->vHeadDim == V_HEAD_DIM_64) ||
            (sfaInfo_->qkHeadDim == QK_HEAD_DIM_192 && sfaInfo_->ropeHeadDim == ROPE_HEAD_DIM_64 &&
             sfaInfo_->vHeadDim == V_HEAD_DIM_128) ||
            (sfaInfo_->qkHeadDim == QK_HEAD_DIM_128 && sfaInfo_->ropeHeadDim == ROPE_HEAD_DIM_64 &&
             sfaInfo_->vHeadDim == V_HEAD_DIM_128)) {
            return true;
        }
    }
    return false;
}

void SfaTilingNonQuant::GenTilingKey()
{
    uint32_t inputQType = static_cast<uint32_t>(sfaInfo_->inputQType);
    uint32_t inputKvType = static_cast<uint32_t>(sfaInfo_->inputKvType);
    uint32_t outputType = static_cast<uint32_t>(sfaInfo_->outputType);
    uint8_t layoutQuery = static_cast<uint8_t>(sfaInfo_->inputLayout);
    uint8_t layoutKV = static_cast<uint8_t>(sfaInfo_->inputKvLayout);
    uint32_t paVal = static_cast<uint32_t>((sfaInfo_->pageAttentionFlag && sfaInfo_->s2Size != 0) ? 1U : 0U);
    uint32_t softmaxBrcbFlagVal = static_cast<uint8_t>((softmaxWithBrcbFlag_) ? 1U : 0U);

    tilingKey_ = GET_TPL_TILING_KEY(0U, paVal, softmaxBrcbFlagVal, layoutQuery, layoutKV);
    OPS_LOG_I(sfaInfo_->opName, "SFA tilingKey_: %lu.", tilingKey_);
}

