190	void SfaTilingNonQuant::CalcInnerSize(uint32_t s2Size)
191	{
192	    if (sfaInfo_->inputLayout == TilingKeyLayout::TND || sfaInfo_->inputLayout == TilingKeyLayout::NTD) {
193	        uint32_t sInnerSize[3U] = {8192U, 4096U, 2048U};
194	        uint32_t idx = std::min(sfaInfo_->gSize / 5U, 2U);
195	        sInnerSize_ = sInnerSize[idx];
196	    } else {
197	        if (sfaInfo_->s1Size <= S1_SIZE_16) {
198	            /**
199	            * V1阶段分配用于存放mm1结果的UB大小为32K, 当计算的数据类型为float时，其可以存放8192个元素.
200	            * 另外, 需要保证单次计算不会切分S2, 那么S2的内切大小最大为8192, 所以将默认值设置为8192
201	            */
202	            sInnerSize_ = MAX_SPLIT_SIZE; // 8192
203	
204	            /** 当前版本限制workspace大小不超过32MB，否则会影响网络中前后算子性能，
205	            *  GQA场景下 nNumOfQInOneGroup和sInnerSize_切分大小直接影响workspace大小,
206	            *  具体计算参考CalcWorkSpace函数，这里根据nNumOfQInOneGroup将sInnerSize_
207	            *  分为8192，4096，2048三档，nNumOfQInOneGroup增大时减小sInnerSize_，
208	            *   保证最终workspace大小不超过32MB。
209	            */
210	            uint32_t sInnerSize[3U] = {8192U, 4096U, 2048U};
211	            uint32_t idx = std::min(sfaInfo_->gSize / 5U, 2U);
212	            sInnerSize_ = sInnerSize[idx];
213	        } else {
214	            bool highPreciseFlag = !((static_cast<uint32_t>(sfaInfo_->innerPrecise) & 1U));
215	            sInnerSize_ =
216	                ((highPreciseFlag && sfaInfo_->inputQType == ge::DT_FLOAT16) || sfaInfo_->inputQType == ge::DT_BF16)
217	                    ? S_INNER_SIZE_512
218	                    : S_INNER_SIZE_1024;
219	        }
220	    }
221	    if (sfaInfo_->attenMaskFlag && (sfaInfo_->sparseMode == SPARSE_MODE_2 || sfaInfo_->sparseMode == SPARSE_MODE_3 ||
222	                                    sfaInfo_->sparseMode == SPARSE_MODE_4)) {
223	        sInnerSize_ = std::min(sInnerSize_, S_INNER_SIZE_1024); // attention mask压缩场景，基本块最大支持1024*1024
224	    }
225	    // PA特性泛化场景，blockSize可能为112等值，无法被sInnerSize_整除，当step*base跨block时，搬运处理复杂，通过向下对齐避免
226	    if (sfaInfo_->pageAttentionFlag && sfaInfo_->blockSize != 0) {
227	        uint32_t blockSize = static_cast<uint32_t>(sfaInfo_->blockSize);
228	        if ((sInnerSize_ > blockSize) && (sInnerSize_ % blockSize != 0)) {
229	            sInnerSize_ = (sInnerSize_ / blockSize) * blockSize;
230	        }
231	    }
232	    sInnerLoopTimes_ = (s2Size + sInnerSize_ - static_cast<uint32_t>(1)) / sInnerSize_;
233	    sInnerSizeTail_ = s2Size - (sInnerLoopTimes_ - static_cast<uint32_t>(1)) * sInnerSize_;
234	    // tiling下沉 && flash decoder场景时，sInnerSize_基块大小不按照真实值修改
235	    // 否则会导致 tiling下沉 && flash decoder 场景时开辟workspace空间大小小于真实运行时所需的workspace大小
236	    if (sInnerSize_ > s2Size) {
237	        sInnerSize_ = s2Size;
238	    }
239	    sInnerSizeAlign_ = Align(sInnerSize_, BYTE_BLOCK); // 元素个数按照基本块大小对齐
240	    CalcMBaseSize();
241	}
