bool SfaTilingNonQuant::IsFlashDecode(uint32_t coreNum)
{
    return false;
}

bool SfaTilingNonQuant::DealSameSeqEachBatch()
{
    if (!sfaInfo_->batchContinuousFlag) {
        if (sfaInfo_->actualSeqLenFlag) {
            return sfaInfo_->isSameActualseq;
        } else {
            return sfaInfo_->isSameSeqAllKVTensor;
        }
    } else {
        return sfaInfo_->isSameActualseq;
    }
}

void SfaTilingNonQuant::ZeroTensorProcess()
{
    if (sfaInfo_->s2Size == 0) {
        /*
         * 1024，空tensor场景下，作为默认值完成后续计算
         * 避免matmal tiling  softmax tiling异常
         * kernel计算使用真实的seqSize=0, 与actuseq_len流程归一
         */
        sfaInfo_->s2Size = 1024;
    }
}

void SfaTilingNonQuant::InitParams()
{
    perfMode_ = IfaPerfMode::CUBE_VIEW_MM;
    coreNum_ = aicNum_;
    blockDim_ = aicNum_; // Tiling下沉首次Tiling也会校验blockDim_是否为0，将blockDim_设置为aicNum_，实际不生效

    headDimAlign_ = Align(sfaInfo_->qkHeadDim, BYTE_BLOCK); // 元素个数按照基本块大小对齐
    ZeroTensorProcess();
}

void SfaTilingNonQuant::CalcInnerSize(uint32_t s2Size)
{
    if (sfaInfo_->inputLayout == TilingKeyLayout::TND || sfaInfo_->inputLayout == TilingKeyLayout::NTD) {
        uint32_t sInnerSize[3U] = {8192U, 4096U, 2048U};
        uint32_t idx = std::min(sfaInfo_->gSize / 5U, 2U);
        sInnerSize_ = sInnerSize[idx];
    } else {
        if (sfaInfo_->s1Size <= S1_SIZE_16) {
            /**
            * V1阶段分配用于存放mm1结果的UB大小为32K, 当计算的数据类型为float时，其可以存放8192个元素.
            * 另外, 需要保证单次计算不会切分S2, 那么S2的内切大小最大为8192, 所以将默认值设置为8192
            */
            sInnerSize_ = MAX_SPLIT_SIZE; // 8192

            /** 当前版本限制workspace大小不超过32MB，否则会影响网络中前后算子性能，
            *  GQA场景下 nNumOfQInOneGroup和sInnerSize_切分大小直接影响workspace大小,
            *  具体计算参考CalcWorkSpace函数，这里根据nNumOfQInOneGroup将sInnerSize_
            *  分为8192，4096，2048三档，nNumOfQInOneGroup增大时减小sInnerSize_，
            *   保证最终workspace大小不超过32MB。
            */
            uint32_t sInnerSize[3U] = {8192U, 4096U, 2048U};
            uint32_t idx = std::min(sfaInfo_->gSize / 5U, 2U);
            sInnerSize_ = sInnerSize[idx];
        } else {
            bool highPreciseFlag = !((static_cast<uint32_t>(sfaInfo_->innerPrecise) & 1U));
            sInnerSize_ =
                ((highPreciseFlag && sfaInfo_->inputQType == ge::DT_FLOAT16) || sfaInfo_->inputQType == ge::DT_BF16)
                    ? S_INNER_SIZE_512
                    : S_INNER_SIZE_1024;
        }
    }
    if (sfaInfo_->attenMaskFlag && (sfaInfo_->sparseMode == SPARSE_MODE_2 || sfaInfo_->sparseMode == SPARSE_MODE_3 ||
                                    sfaInfo_->sparseMode == SPARSE_MODE_4)) {
        sInnerSize_ = std::min(sInnerSize_, S_INNER_SIZE_1024); // attention mask压缩场景，基本块最大支持1024*1024
    }
    // PA特性泛化场景，blockSize可能为112等值，无法被sInnerSize_整除，当step*base跨block时，搬运处理复杂，通过向下对齐避免
    if (sfaInfo_->pageAttentionFlag && sfaInfo_->blockSize != 0) {
        uint32_t blockSize = static_cast<uint32_t>(sfaInfo_->blockSize);
        if ((sInnerSize_ > blockSize) && (sInnerSize_ % blockSize != 0)) {
            sInnerSize_ = (sInnerSize_ / blockSize) * blockSize;
        }
    }
    sInnerLoopTimes_ = (s2Size + sInnerSize_ - static_cast<uint32_t>(1)) / sInnerSize_;
    sInnerSizeTail_ = s2Size - (sInnerLoopTimes_ - static_cast<uint32_t>(1)) * sInnerSize_;
    // tiling下沉 && flash decoder场景时，sInnerSize_基块大小不按照真实值修改
    // 否则会导致 tiling下沉 && flash decoder 场景时开辟workspace空间大小小于真实运行时所需的workspace大小
    if (sInnerSize_ > s2Size) {
        sInnerSize_ = s2Size;
    }
    sInnerSizeAlign_ = Align(sInnerSize_, BYTE_BLOCK); // 元素个数按照基本块大小对齐
    CalcMBaseSize();
}

void SfaTilingNonQuant::CalcMBaseSize()
{
    OPS_LOG_I(sfaInfo_->opName, "sfaInfo_->inputLayout: %u", sfaInfo_->inputLayout);

    if (sfaInfo_->inputLayout == TilingKeyLayout::TND || sfaInfo_->inputLayout == TilingKeyLayout::BSH_BSND) {
        mBaseSize_ = sfaInfo_->gSize;
    } else {
        mBaseSize_ = 1;
    }

    softmaxWithBrcbFlag_ = (mBaseSize_ <= M_BASE_SIZE_128);

    OPS_LOG_I(sfaInfo_->opName,
              "SFA sInnerSize_:%u sInnerSizeAlign_:%u mBaseSize_:%u softmaxWithBrcbFlag_:%u.",
              sInnerSize_,
              sInnerSizeAlign_,
              mBaseSize_,
              softmaxWithBrcbFlag_);
}

void SfaTilingNonQuant::CreateSplitInput(SfaSplitCoreBaseInfo &baseInfo)
{
    // 构造分核输入参数
    baseInfo.bSize = sfaInfo_->bSize;
    baseInfo.n2Size = sfaInfo_->n2Size;
    baseInfo.gSize = sfaInfo_->gSize;
    baseInfo.s2Size = sfaInfo_->s2Size;
    baseInfo.s1Size = sfaInfo_->s1Size;
    baseInfo.actualLenQDims = sfaInfo_->actualLenQDims;
    baseInfo.actualLenKvDims = sfaInfo_->actualLenDims;

    baseInfo.sparseMode = sfaInfo_->sparseMode;
    baseInfo.sparseBlockSize = static_cast<uint32_t>(sfaInfo_->sparseBlockSize);
    baseInfo.sparseBlockCount = sfaInfo_->sparseBlockCount;

    if (sfaInfo_->opParamInfo.actualSeqLengthsQ.tensor != nullptr) {
        baseInfo.actualSeqS1Size = sfaInfo_->opParamInfo.actualSeqLengthsQ.tensor->GetData<int64_t>();
        baseInfo.isAccumSeqS1 = sfaInfo_->isAccumQSeq;
    }
    if (sfaInfo_->opParamInfo.actualSeqLengths.tensor != nullptr) {
        baseInfo.actualSeqS2Size = sfaInfo_->opParamInfo.actualSeqLengths.tensor->GetData<int64_t>();
        baseInfo.isAccumSeqS2 = sfaInfo_->isAccumKVSeq;
    }
}

void SfaTilingNonQuant::CreateSplitOutput(SfaOuterSplitParams &outerSplitParams,
                                          SfaFlashDecodeParams &fDParams,
                                          SfaSplitCoreRes &res)
{
    outerSplitParams.bN2End = tilingData_.outerSplitParams.get_bN2End();
    outerSplitParams.gS1End = tilingData_.outerSplitParams.get_gS1End();
    outerSplitParams.s2End = tilingData_.outerSplitParams.get_s2End();

    tilingData_.fdParams.set_gS1BaseSizeOfFd(mFdBaseSize_);
    fDParams.bN2IdxOfFdHead = tilingData_.fdParams.get_bN2IdxOfFdHead();
    fDParams.gS1IdxOfFdHead = tilingData_.fdParams.get_gS1IdxOfFdHead();
    fDParams.s2SplitNumOfFdHead = tilingData_.fdParams.get_s2SplitNumOfFdHead();
    fDParams.s2SplitStartIdxOfCore = tilingData_.fdParams.get_s2SplitStartIdxOfCore();
    fDParams.gS1BaseSizeOfFd = tilingData_.fdParams.get_gS1BaseSizeOfFd();
    fDParams.gS1SplitNumOfFdHead = tilingData_.fdParams.get_gS1SplitNumOfFdHead();
    fDParams.gS1LastPartSizeOfFdHead = tilingData_.fdParams.get_gS1LastPartSizeOfFdHead();
    fDParams.gS1IdxEndOfFdHead = tilingData_.fdParams.get_gS1IdxEndOfFdHead();
    fDParams.gS1IdxEndOfFdHeadSplit = tilingData_.fdParams.get_gS1IdxEndOfFdHeadSplit();

    res.numOfFdHead = 0;
    res.maxS2SplitNum = 1;
    res.usedCoreNum = aicNum_;
}

void SfaTilingNonQuant::Split()
{
    uint32_t s2SizeInput = static_cast<uint32_t>(sfaInfo_->s2Size);
    CalcInnerSize(s2SizeInput);

    SfaSplitCoreBaseInfo baseInfo;
    CreateSplitInput(baseInfo);

    SfaInnerSplitParams innerSplitParams;
    innerSplitParams.s1GBaseSize = mBaseSize_;
    innerSplitParams.s2BaseSize = sInnerSize_;
    tilingData_.innerSplitParams.set_mBaseSize(innerSplitParams.s1GBaseSize);
    tilingData_.innerSplitParams.set_s2BaseSize(innerSplitParams.s2BaseSize);

    SfaOuterSplitParams outerSplitParams;
    SfaFlashDecodeParams fDParams;
    SfaSplitCoreRes res;
    CreateSplitOutput(outerSplitParams, fDParams, res);

    SfaSplitCore(baseInfo, innerSplitParams, aicNum_, outerSplitParams, fDParams, res);
    if (res.numOfFdHead > aicNum_ || res.usedCoreNum > aicNum_ || res.maxS2SplitNum > aicNum_ + 1) {
        OPS_LOG_E(sfaInfo_->opName,
                  "used_core_num: %u, num_of_fd_head: %u, max_s2_split_num: %u, aic_num: %u",
                  res.usedCoreNum,
                  res.numOfFdHead,
                  res.maxS2SplitNum,
                  aicNum_);
    }

