void SfaTilingNonQuant::CalcMmResSize()
{
    int64_t mSize = std::min(sfaInfo_->gSize * sfaInfo_->s1Size, mBaseSize_);
    mm1ResSize_ = static_cast<int64_t>(sInnerSizeAlign_) * mSize;
