49	bool GetPaValueD(gert::TilingContext *context, int64_t &valueD)
50	{
51	    auto attrs = context->GetAttrs();
52	    int64_t numHeads = static_cast<int64_t>(*attrs->GetAttrPointer<uint32_t>(ATTR_N_INDEX));
53	    int64_t numKvHeads = static_cast<int64_t>(*attrs->GetAttrPointer<uint32_t>(ATTR_NUM_KV_HEADS_INDEX));
54	    if (numKvHeads == 0) {
55	        numKvHeads = numHeads;
56	    }
57	    auto vStorageShape = context->GetInputShape(VALUE_INDEX)->GetStorageShape();
58	    if (vStorageShape.GetDimNum() == DIM_BSH) {
59	        valueD = vStorageShape.GetDim(BSH_H_IDX) / numKvHeads; // BnBsH
60	    } else if (vStorageShape.GetDimNum() == DIM_BNSD_OR_BSND) {
61	        valueD = vStorageShape.GetDim(BNSD_D_IDX); // BnNBsD or BnBsND
62	    } else if (vStorageShape.GetDimNum() == DIM_NZ) {
63	        valueD = vStorageShape.GetDim(NZ_D1_IDX) * vStorageShape.GetDim(NZ_D0_IDX); // NZ: BnND1BsD0
64	    } else {
65	        return false;
66	    }
67	    return true;
68	}
69	
70	bool GetValueD(gert::TilingContext *context, int64_t &valueD)
71	{
72	    auto vShape = context->GetInputShape(VALUE_INDEX);
73	    if (vShape == nullptr) {
74	        return false;
75	    }
76	    auto vStorageShape = vShape->GetStorageShape();
77	
78	    bool isPageAttention = context->GetOptionalInputShape(BLOCK_TABLE_INDEX) != nullptr;
79	    if (isPageAttention) {
80	        return GetPaValueD(context, valueD);
81	    }
82	
83	    auto attrs = context->GetAttrs();
84	    int64_t numHeads = static_cast<int64_t>(*attrs->GetAttrPointer<uint32_t>(ATTR_N_INDEX));
85	    int64_t numKvHeads = static_cast<int64_t>(*attrs->GetAttrPointer<uint32_t>(ATTR_NUM_KV_HEADS_INDEX));
86	    if (numKvHeads == 0) {
87	        numKvHeads = numHeads;
88	    }
89	    const std::string inputLayoutStr = std::string(context->GetAttrs()->GetAttrPointer<char>(ATTR_INPUT_LAYOUT_INDEX));
90	    if (inputLayoutStr == "BNSD_BSND" ||
91	        inputLayoutStr == "BSND_BNSD" ||
92	        inputLayoutStr == "BNSD_NBSD" ||
93	        inputLayoutStr == "BSND_NBSD" ||
94	        inputLayoutStr == "BNSD" ||
95	        inputLayoutStr == "BSND") {
96	        if (vStorageShape.GetDimNum() != DIM_BNSD_OR_BSND) {
97	            return false;
98	        }
99	        valueD = vStorageShape.GetDim(BNSD_D_IDX);
100	    } else if (inputLayoutStr == "BSH" ||
101	        inputLayoutStr == "BSH_NBSD" ||
102	        inputLayoutStr == "BSH_BNSD") {
103	        if (vStorageShape.GetDimNum() != DIM_BSH) {
104	            return false;
105	        }
106	        valueD = vStorageShape.GetDim(BSH_H_IDX) / numKvHeads;
107	    } else if (inputLayoutStr == "TND" ||
108	        inputLayoutStr == "NTD" ||
109	        inputLayoutStr == "TND_NTD" ||
110	        inputLayoutStr == "NTD_TND") {
111	        if (vStorageShape.GetDimNum() != DIM_TND) {
112	            return false;
113	        }
114	        valueD = vStorageShape.GetDim(TND_NTD_D_IDX);
115	    } else {
116	        return false;
117	    }
