template <typename T>
static inline auto Min(T a, T b) -> T
{
    return (a > b) ? b : a;
}

template <typename T>
static inline auto Align(T num, T rnd) -> T
{
    return (rnd == 0) ? 0 : ((num + rnd - 1) / rnd * rnd);
}

